#!/usr/bin/env node
// Validates every skill and generates the catalog from the skills themselves, so nothing drifts.
//
//   node scripts/catalog.mjs          write .claude-plugin/marketplace.json and the README catalog
//   node scripts/catalog.mjs --check  fail (exit 1) if a skill is invalid or a generated file is stale (CI)
//
// Source of truth: each skills/<name>/SKILL.md frontmatter (name, description, metadata.category,
// metadata.version, metadata.summary, metadata.tags) and categories.json. Node 18+, no dependencies.
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
const MARKETPLACE = "vishal-agent-skills";
const OWNER = { name: "Vishal Gupta", url: "https://github.com/vishalguptax" };
const START = "<!-- catalog:start (generated by scripts/catalog.mjs; edit the skills, not this) -->";
const END = "<!-- catalog:end -->";

const problems = [];
const categories = JSON.parse(readFileSync(path.join(root, "categories.json"), "utf8")).categories;
const categoryIds = new Set(categories.map((c) => c.id));

/** Parses the YAML subset skills use: `key: value` lines and one level of nested keys. */
function frontmatter(text, file) {
  const m = text.match(/^---\n([\s\S]*?)\n---\n/);
  if (!m) {
    problems.push(`${file}: no YAML frontmatter`);
    return {};
  }
  const data = {};
  let parent = null;
  for (const line of m[1].split("\n")) {
    if (!line.trim() || line.trim().startsWith("#")) continue;
    const kv = line.match(/^(\s*)([\w-]+):\s*(.*)$/);
    if (!kv) {
      problems.push(`${file}: can't read frontmatter line: ${line}`);
      continue;
    }
    const [, indent, key, raw] = kv;
    const value = raw.replace(/^"(.*)"$/, "$1").replace(/^'(.*)'$/, "$1");
    if (indent.length === 0) {
      if (raw === "") {
        data[key] = {};
        parent = key;
      } else {
        data[key] = value;
        parent = null;
      }
    } else if (parent) {
      data[parent][key] = value;
    } else {
      problems.push(`${file}: unexpected indentation: ${line}`);
    }
  }
  return data;
}

const skillsDir = path.join(root, "skills");
const skills = readdirSync(skillsDir, { withFileTypes: true })
  .filter((d) => d.isDirectory() && !d.name.startsWith("."))
  .map((d) => {
    const dir = path.join(skillsDir, d.name);
    const rel = `skills/${d.name}/SKILL.md`;
    if (!existsSync(path.join(dir, "SKILL.md"))) {
      problems.push(`skills/${d.name}: no SKILL.md`);
      return null;
    }
    const fm = frontmatter(readFileSync(path.join(dir, "SKILL.md"), "utf8"), rel);
    const meta = fm.metadata ?? {};
    if (fm.name !== d.name) problems.push(`${rel}: name "${fm.name}" must match its folder "${d.name}"`);
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(d.name) || d.name.length > 64) problems.push(`${rel}: the folder name must be kebab-case, at most 64 characters`);
    if (!fm.description) problems.push(`${rel}: missing description`);
    else if (fm.description.length > 1024) problems.push(`${rel}: description is ${fm.description.length} characters (max 1024)`);
    else if (/[<>]/.test(fm.description)) problems.push(`${rel}: description can't contain < or >`);
    if (!categoryIds.has(meta.category)) problems.push(`${rel}: metadata.category "${meta.category ?? ""}" is not in categories.json`);
    if (!/^\d+\.\d+\.\d+$/.test(meta.version ?? "")) problems.push(`${rel}: metadata.version must be x.y.z`);
    if (!meta.summary) problems.push(`${rel}: missing metadata.summary (one line for the catalog)`);
    else if (meta.summary.length > 300) problems.push(`${rel}: metadata.summary is over 300 characters`);
    if (!existsSync(path.join(dir, "README.md"))) problems.push(`skills/${d.name}: no README.md (the human docs for this skill)`);
    if (!existsSync(path.join(root, "evals", d.name, "evals.json"))) problems.push(`evals/${d.name}/evals.json: missing (every skill ships with its test prompts)`);
    return {
      name: d.name,
      category: meta.category,
      version: meta.version,
      summary: meta.summary,
      tags: (meta.tags ?? "").split(",").map((t) => t.trim()).filter(Boolean),
    };
  })
  .filter(Boolean)
  .sort((a, b) => a.name.localeCompare(b.name));

// ---------- generated files ----------

const marketplace = {
  name: MARKETPLACE,
  owner: OWNER,
  metadata: {
    description: "Vishal Gupta's agent skills: practical, tested skills for Claude Code and other AI coding agents.",
    version: "1.0.0",
  },
  plugins: skills.map((s) => ({
    name: s.name,
    description: s.summary,
    version: s.version,
    category: s.category,
    keywords: s.tags,
    source: "./",
    strict: false,
    skills: [`./skills/${s.name}`],
  })),
};
const marketplaceText = `${JSON.stringify(marketplace, null, 2)}\n`;

const catalogLines = [START, ""];
for (const category of categories) {
  const inCategory = skills.filter((s) => s.category === category.id);
  if (inCategory.length === 0) continue;
  catalogLines.push(`### ${category.title}`, "", `${category.description}`, "", "| Skill | What it does | Version |", "|---|---|---|");
  for (const s of inCategory) catalogLines.push(`| [**${s.name}**](skills/${s.name}/) | ${s.summary} | ${s.version} |`);
  catalogLines.push("");
}
catalogLines.push(`_${skills.length} skill${skills.length === 1 ? "" : "s"}. Categories with no skills yet are listed in [categories.json](categories.json)._`, "", END);
const catalog = catalogLines.join("\n");

const readmePath = path.join(root, "README.md");
const readme = readFileSync(readmePath, "utf8");
const startAt = readme.indexOf(START);
const endAt = readme.indexOf(END);
if (startAt < 0 || endAt < startAt) problems.push("README.md: catalog markers are missing");
const newReadme = startAt >= 0 && endAt > startAt ? readme.slice(0, startAt) + catalog + readme.slice(endAt + END.length) : readme;

const marketplacePath = path.join(root, ".claude-plugin", "marketplace.json");
const currentMarketplace = existsSync(marketplacePath) ? readFileSync(marketplacePath, "utf8") : "";

if (problems.length > 0) {
  console.error(problems.map((p) => `✗ ${p}`).join("\n"));
  process.exit(1);
}
if (check) {
  const stale = [];
  if (currentMarketplace !== marketplaceText) stale.push(".claude-plugin/marketplace.json");
  if (readme !== newReadme) stale.push("README.md catalog");
  if (stale.length > 0) {
    console.error(`✗ Out of date: ${stale.join(", ")}. Run: node scripts/catalog.mjs`);
    process.exit(1);
  }
  console.log(`✓ ${skills.length} skill(s) valid; marketplace and README catalog up to date.`);
} else {
  writeFileSync(marketplacePath, marketplaceText);
  writeFileSync(readmePath, newReadme);
  console.log(`✓ ${skills.length} skill(s) valid; wrote .claude-plugin/marketplace.json and the README catalog.`);
}
